// only; a ceiling is never invented. Dedupe by name BEFORE the request, or
// Postgres throws "ON CONFLICT DO UPDATE cannot affect row a second time".
const res = $input.first().json;
const byTab = {};
for (const vr of (res.valueRanges || [])) {
  byTab[String(vr.range).split('!')[0].replace(/'/g, '')] = vr.values || [];
}
function rows(tab) {
  const v = byTab[tab] || [];
  if (!v.length) return [];
  const h = v[0];
  return v.slice(1).map(function (r) {
    const o = {};
    h.forEach(function (k, i) { o[k] = (r[i] === undefined ? '' : r[i]); });
    return o;
  });
}
const S = rows('STARTUPS'), I = rows('INVESTORS'), C = rows('INVESTOR_CRITERIA');
const nz = function (s) { return String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, ''); };
const g = function (r, k) { const v = String(r[k] == null ? '' : r[k]).trim(); return v === '' ? null : v; };
const skips = [];
