const UNIT = { cr: 1, crore: 1, crores: 1, l: 0.01, lac: 0.01, lacs: 0.01, lakh: 0.01, lakhs: 0.01 };
const INR_RANGE = /INR\s*([\d.]+)\s*(cr|crores|crore|lacs|lac|lakhs|lakh|l)?\s*(?:-|to)\s*([\d.]+)\s*(cr|crores|crore|lacs|lac|lakhs|lakh|l)/i;
const INR_ONE = /INR\s*([\d.]+)\s*(cr|crores|crore|lacs|lac|lakhs|lakh|l)/i;
const BARE_RANGE = /([\d.]+)\s*(cr|crores|crore|lacs|lac|lakhs|lakh|l)?\s*(?:-|to)\s*([\d.]+)\s*(cr|crores|crore|lacs|lac|lakhs|lakh|l)/i;
const BARE_ONE = /([\d.]+)\s*(cr|crores|crore)/i;
const CEILING = /up\s*to|max|below/i;
const FUNDSIZE = /fund|corpus|aum/i;
const HAS_USD = /us\$|usd|\$/i;
const r2 = function (x) { return Math.round(x * 100) / 100; };

function money(s) {
  s = String(s == null ? '' : s).trim();
  if (!s) return [null, null, 'blank'];
  let m = INR_RANGE.exec(s);
  if (m) { const u2 = UNIT[m[4].toLowerCase()]; const u1 = UNIT[(m[2] || '').toLowerCase()] || u2;
           return [r2(parseFloat(m[1]) * u1), r2(parseFloat(m[3]) * u2), null]; }
  m = INR_ONE.exec(s);
  if (m) { const v = r2(parseFloat(m[1]) * UNIT[m[2].toLowerCase()]);
           return CEILING.test(s) ? [null, v, null] : [v, null, null]; }
  m = BARE_RANGE.exec(s);
  if (m) { const u2 = UNIT[m[4].toLowerCase()]; const u1 = UNIT[(m[2] || '').toLowerCase()] || u2;
           return [r2(parseFloat(m[1]) * u1), r2(parseFloat(m[3]) * u2), null]; }
  m = BARE_ONE.exec(s);
  if (m && !FUNDSIZE.test(s)) { const v = r2(parseFloat(m[1]));
           return CEILING.test(s) ? [null, v, null] : [v, null, null]; }
