// how the subject line leads. A range or a word like 'Undisclosed' keeps its
// text and gets no number, because inventing one would be a guess.
function raiseParts(sv) {
  const t = String(sv == null ? '' : sv).trim();
  if (!t) { return [null, null, null]; }
  const u = /US?\$\s*([\d.]+)\s*([MK])?/i.exec(t);
  const i = /INR\s*([\d.]+)\s*Cr\b/i.exec(t);
  if (u && (!i || u.index < i.index)) {
    const n = parseFloat(u[1]); const unit = (u[2] || 'M').toUpperCase();
    return ['USD', r2(unit === 'K' ? n / 1000 : n), t];
