const HOT = {};
['Spintly','Bon Cuisine','EosNox','HYRGPT','Talent Recruit','Hoora','CLIKD','MindWox','MentorCloud','Road Athena','LearningPad'].forEach(function (x) { HOT[nz(x)] = 1; });

const startups = []; const seenS = {};
for (const r of S) {
