  if (seenS[nz(name)]) { log('startup', name, 'name', 'duplicate name, first kept'); continue; }
  seenS[nz(name)] = 1;
  const desk = String(r.desk || '').trim().toUpperCase();
  const bucket = HOT[nz(name)] ? 'HOT10' : (desk === 'ANGEL' ? 'A' : (desk === 'MIDDLE' ? 'C' : 'UNASSIGNED'));
  const active = String(r.active || '').trim().toLowerCase();
  let status = 'live';
  if (active === 'no') { status = 'blocked'; }
  else if (active !== 'yes') { log('startup', name, 'status', 'active blank, defaulted to live'); }
  const mm = money(r.raise_inr_cr);
  const rp = raiseParts(r.raise_inr_cr);
  let ask = null;
  if (mm[0] !== null && mm[1] !== null) { log('startup', name, 'ask_current_cr', 'a range, not a single ask', r.raise_inr_cr || ''); }
  else if (mm[0] !== null) { ask = mm[0]; }
  else if (mm[1] !== null) { ask = mm[1]; }
  else if (mm[2] !== 'blank') { log('startup', name, 'ask_current_cr', mm[2], r.raise_inr_cr || ''); }
