    cheque_min_cr: cm[0], cheque_max_cr: cm[1], cheque_as_written: g(r, 'cheque_inr_cr'),
    geography: (String(c.geography_scope || '').trim() || null), do_not_contact: (!!g(r, 'do_not_contact')) || st === 'DNC',
    last_contacted_on: last, contacted_by: g(r, 'contacted_by'),
