const ok = function (r) { return r && r.statusCode >= 200 && r.statusCode < 300; };
const why = function (r) { if (!r) return 'no response'; if (ok(r)) return 'ok'; return 'HTTP ' + r.statusCode + ' ' + JSON.stringify(r.body).slice(0, 200); };
const reasons = {};
for (const k of b.skips) { reasons[k.reason] = (reasons[k.reason] || 0) + 1; }
return [{ json: {
  ran_at_ist: new Date(Date.now() + 19800000).toISOString().replace('T', ' ').slice(0, 19) + ' IST',
